  .main-layout {
    flex-direction: column;
  }
  .sidebar {
    width: 100%;
    min-width: 0;
    border-right: none;
    border-bottom: 1px solid #2d2d30;
    padding: 18px 10px 0 10px;
  }
  .main-content {
    padding: 24px 4vw 24px 4vw;
  }
}
@media (max-width: 760px) {
  .sidebar {
    display: none;
  }
  .main-content {
    padding: 18px 2vw;
  }
  .auth-forms { flex-direction: column; padding: 15px 8px;}
}

/* Typography overrides for light modern look */
h1,h2,h3,h4,h5 { font-family: inherit; font-weight: 700; margin-top: 0; color:var(--primary);}
h1 { font-size: 2.65rem; }
h2 { font-size: 1.7rem;}
h3 { font-size: 1.13rem;}
p,li,label { color:var(--text-color);};/* Recipe List & Cards */
.recipe-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 24px;
}

.recipe-card {
  background: #fff;
  border-radius: 8px;
  box-shadow: 0 2px 16px 0 rgba(90, 90, 109, 0.07);
  padding: 24px 20px;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  border: 1px solid var(--border-color);
}

.recipe-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.97rem;
  color: var(--text-secondary);
  margin-bottom: 2px;
  gap: 16px;
}
.fav-star {
  font-size: 1.18em;
  background: none;
  border: none;
  cursor: pointer;
  color: #999;
  margin-left: 12px;
  transition: color 0.19s;
}
.fav-star:hover { color: var(--accent); }
.recipe-desc {
  margin-bottom: 10px;
  color: var(--text-secondary);
  min-height: 42px;
}
.recipe-card .btn { width: fit-content; margin-top: 8px; }

.empty-results {
  margin: 64px auto;
  color: var(--text-secondary);
  font-size: 1.11rem;
  text-align: center;
}

.recipe-detail {
  background: #fff;
  border-radius: 10px;
  padding: 34px 32px 28px 32px;
  max-width: 600px;
  margin: 0 auto;
  box-shadow: 0 3px 28px 0 rgba(140, 120, 170, .14);
  border: 1px solid var(--border-color);
}

.detail-header {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 1.2rem;
  color: var(--primary);
  font-weight: 600;
}

.fav-star-large {
  font-size: 1.6rem;
  background: none;
  border: none;
  margin-left: 10px;
  cursor: pointer;
  transition: color 0.18s;
}

.fav-star-large:hover { color: var(--accent); }

.detail-section {
  margin: 16px 0;
}

.detail-section strong {
  font-size: 1.06rem;
}
.detail-buttons {
  display: flex;
  gap: 16px;
  margin-top: 20px;
}

